begin;

-- Bundled catalog photos work on any deployment origin. Keep the existing HTTPS option.
alter table public.products drop constraint if exists products_image_url_check;
alter table public.products add constraint products_image_url_check
  check (image_url like 'https://%' or image_url ~ '^/brand/mywonderbox/[a-z0-9-]+[.]webp$');

-- Existing rows keep their identifiers, prices, descriptions and photos.
insert into public.products (id,slug,name,description,short_description,price_minor,age_label,
  image_url,images,categories,dimensions,safety_info,stock,published,packaging,sort_order)
select p.id,p.slug,p.name,p.description,p.short_description,p.price_minor,p.age_label,
  p.image_url,p.images,p.categories,p.dimensions,p.safety_info,p.stock,p.published,p.packaging,p.sort_order
from (values
  ('{"id":"a301a032-06af-4001-befd-35f98ac0dc03","slug":"mywonderbox-bag-blue","name":"MyWonderBox — ბიჭის სიურპრიზ-პარკი","short_description":"აღმოაჩინე, რა იმალება შიგნით!","description":"პარკში იგივე სიურპრიზები გელოდება, რაც შესაბამის ყუთში. განსხვავება მხოლოდ გარე შეფუთვაა. შიგთავსი შეიძლება განსხვავდებოდეს და კონკრეტული ნივთი ან ბრენდი გარანტირებული არ არის.","price_minor":2490,"age_label":"4–10 წელი","stock":50,"published":true,"image_url":"/brand/mywonderbox/bag-blue.webp","images":["/brand/mywonderbox/bag-blue-detail.webp"],"categories":["სათამაშოები","თამაშები","შემოქმედებითი ნივთები"],"dimensions":"25 × 32 × 10 სმ","safety_info":"პარკი შეიძლება შეიცავდეს მცირე ნაწილებს. არ მისცე 3 წლამდე ბავშვს ისეთი ნივთი, რომელიც შეიცავს მცირე ნაწილებს ან რომლის ასაკობრივი ნიშნულიც მას არ შეესაბამება. გამოიყენეთ ზრდასრულის მეთვალყურეობით. თამაშამდე მოაშორე შეფუთვა, ლენტები და დამცავი მასალები. შეამოწმე თითოეული ნივთის ასაკობრივი ნიშნული, გაფრთხილებები და ინსტრუქცია. დაზიანებული ნივთი ბავშვს არ მისცე. ეს ზოგადი მითითებები თითოეული სათამაშოს ინსტრუქციასთან ერთად გამოიყენე.","packaging":"navy-yellow","sort_order":0}'::jsonb),
  ('{"id":"a301a032-06af-4001-befd-35f98ac0dc04","slug":"mywonderbox-bag-pink","name":"MyWonderBox — გოგოს სიურპრიზ-პარკი","short_description":"პატარა სიურპრიზი, დიდი სიხარული!","description":"პარკში იგივე სიურპრიზები გელოდება, რაც შესაბამის ყუთში. განსხვავება მხოლოდ გარე შეფუთვაა. შიგთავსი შეიძლება განსხვავდებოდეს და კონკრეტული ნივთი ან ბრენდი გარანტირებული არ არის.","price_minor":2490,"age_label":"4–10 წელი","stock":50,"published":true,"image_url":"/brand/mywonderbox/bag-pink.webp","images":["/brand/mywonderbox/bag-pink-detail.webp"],"categories":["სათამაშოები","თამაშები","შემოქმედებითი ნივთები"],"dimensions":"25 × 32 × 10 სმ","safety_info":"პარკი შეიძლება შეიცავდეს მცირე ნაწილებს. არ მისცე 3 წლამდე ბავშვს ისეთი ნივთი, რომელიც შეიცავს მცირე ნაწილებს ან რომლის ასაკობრივი ნიშნულიც მას არ შეესაბამება. გამოიყენეთ ზრდასრულის მეთვალყურეობით. თამაშამდე მოაშორე შეფუთვა, ლენტები და დამცავი მასალები. შეამოწმე თითოეული ნივთის ასაკობრივი ნიშნული, გაფრთხილებები და ინსტრუქცია. დაზიანებული ნივთი ბავშვს არ მისცე. ეს ზოგადი მითითებები თითოეული სათამაშოს ინსტრუქციასთან ერთად გამოიყენე.","packaging":"pink-berry","sort_order":1}'::jsonb),
  ('{"id":"a301a032-06af-4001-befd-35f98ac0dc01","slug":"joybox-navy","name":"MyWonderBox — ბიჭებისთვის","short_description":"სიურპრიზის ყუთი ბავშვებისთვის. აირჩიე შენი საყვარელი შეფუთვა.","description":"MyWonderBox ბავშვებისთვის განკუთვნილი სიურპრიზის ყუთია. ზუსტი შიგთავსი გახსნამდე სიურპრიზად რჩება და შეიძლება განსხვავდებოდეს ყუთებს შორის. ფოტოებსა და ანიმაციებში ნაჩვენები სათამაშოები მაგალითებია. კონკრეტული სათამაშო, ბრენდი ან ნივთების რაოდენობა გარანტირებული არ არის. შიგნით მოთავსებული თითოეული ნივთის ასაკობრივი ნიშნული და გამოყენების ინსტრუქცია ცალკე შეამოწმე.","price_minor":2990,"age_label":"4–10 წელი","stock":0,"published":true,"image_url":"/brand/mywonderbox/box-blue.webp","images":[],"categories":["სათამაშოები","თამაშები","შემოქმედებითი ნივთები"],"dimensions":"22 × 20 × 9 სმ","safety_info":"ყუთი შეიძლება შეიცავდეს მცირე ნაწილებს. არ მისცე 3 წლამდე ბავშვს ისეთი ნივთი, რომელიც შეიცავს მცირე ნაწილებს ან რომლის ასაკობრივი ნიშნულიც მას არ შეესაბამება. გამოიყენეთ ზრდასრულის მეთვალყურეობით. თამაშამდე მოაშორე შეფუთვა, ლენტები და დამცავი მასალები. შეამოწმე თითოეული ნივთის ასაკობრივი ნიშნული, გაფრთხილებები და ინსტრუქცია. დაზიანებული ნივთი ბავშვს არ მისცე. ეს ზოგადი მითითებები თითოეული სათამაშოს ინსტრუქციასთან ერთად გამოიყენე.","packaging":"navy-yellow","sort_order":2}'::jsonb),
  ('{"id":"a301a032-06af-4001-befd-35f98ac0dc02","slug":"joybox-berry","name":"MyWonderBox — გოგოებისთვის","short_description":"სიურპრიზის ყუთი ბავშვებისთვის. აირჩიე შენი საყვარელი შეფუთვა.","description":"MyWonderBox ბავშვებისთვის განკუთვნილი სიურპრიზის ყუთია. ზუსტი შიგთავსი გახსნამდე სიურპრიზად რჩება და შეიძლება განსხვავდებოდეს ყუთებს შორის. ფოტოებსა და ანიმაციებში ნაჩვენები სათამაშოები მაგალითებია. კონკრეტული სათამაშო, ბრენდი ან ნივთების რაოდენობა გარანტირებული არ არის. შიგნით მოთავსებული თითოეული ნივთის ასაკობრივი ნიშნული და გამოყენების ინსტრუქცია ცალკე შეამოწმე.","price_minor":2990,"age_label":"4–10 წელი","stock":0,"published":true,"image_url":"/brand/mywonderbox/box-pink.webp","images":[],"categories":["სათამაშოები","თამაშები","შემოქმედებითი ნივთები"],"dimensions":"22 × 20 × 9 სმ","safety_info":"ყუთი შეიძლება შეიცავდეს მცირე ნაწილებს. არ მისცე 3 წლამდე ბავშვს ისეთი ნივთი, რომელიც შეიცავს მცირე ნაწილებს ან რომლის ასაკობრივი ნიშნულიც მას არ შეესაბამება. გამოიყენეთ ზრდასრულის მეთვალყურეობით. თამაშამდე მოაშორე შეფუთვა, ლენტები და დამცავი მასალები. შეამოწმე თითოეული ნივთის ასაკობრივი ნიშნული, გაფრთხილებები და ინსტრუქცია. დაზიანებული ნივთი ბავშვს არ მისცე. ეს ზოგადი მითითებები თითოეული სათამაშოს ინსტრუქციასთან ერთად გამოიყენე.","packaging":"pink-berry","sort_order":3}'::jsonb)
) as source(data)
cross join lateral jsonb_populate_record(null::public.products,source.data) p
on conflict (slug) do nothing;

-- These are the two known cardboard editions, including the original storage slugs.
update public.products set stock = 0
where slug in ('joybox-navy','joybox-berry','mywonderbox-blue','mywonderbox-pink') and stock <> 0;

commit;
